  1	/**
  2	 * Settings View — Repo Parallelizer GUI.
  3	 *
  4	 * Renders three settings sections:
  5	 *   1. **Git Credentials** — table of per-host PATs with add/delete controls.
  6	 *   2. **Repositories Refresh Delay** — number input for `gitPollingIntervalSeconds`
  7	 *      with client-side validation (min 10) and save/feedback.
  8	 *   3. **Webserver URL** — text input for the base URL of the local webserver
  9	 *      that serves the workspace repositories, enabling the "Browse" button in
 10	 *      the workspace-detail view.
 11	 *
 12	 * This view has no side-effects (no polling), so it returns no cleanup function.
 13	 *
 14	 * @param {HTMLElement} container - The `#app` root element supplied by the router.
 15	 * @param {Object}      _params   - Route params (none for this route).
 16	 */
 17	
 18	import { api } from '../api.js';
 19	import { showToast } from '../components/toast.js';
 20	import { showConfirm } from '../components/confirm-dialog.js';
 21	import { APP_NAME_SHORT } from '../utils/constants.js';
 22	import { createFormField, validateRequired } from '../components/form-helpers.js';
 23	import { clearElement } from '../utils/dom.js';
 24	
 25	// ---------------------------------------------------------------------------
 26	// Table rendering
 27	// ---------------------------------------------------------------------------
 28	
 29	/**
 30	 * Build the `<thead>` for the credentials table.
 31	 *
 32	 * @returns {HTMLElement}
 33	 */
 34	function buildTableHead() {
 35	    const thead = document.createElement('thead');
 36	    const tr = document.createElement('tr');
 37	
 38	    ['Host', 'Token', 'Actions'].forEach((label) => {
 39	        const th = document.createElement('th');
 40	        th.textContent = label;
 41	        tr.appendChild(th);
 42	    });
 43	
 44	    thead.appendChild(tr);
 45	    return thead;
 46	}
 47	
 48	/**
 49	 * Build a single `<tr>` for one credential entry.
 50	 *
 51	 * @param {string}            host       - The hostname key.
 52	 * @param {string}            maskedToken - The masked token string (e.g. `****abc1`).
 53	 * @param {function(): void}  onDeleted  - Callback to refresh the table after deletion.
 54	 * @returns {HTMLTableRowElement}
 55	 */
 56	function buildCredentialRow(host, maskedToken, onDeleted) {
 57	    const tr = document.createElement('tr');
 58	    tr.dataset.credHost = host;
 59	
 60	    // ---- Host cell (read-only) ----
 61	    const hostCell = document.createElement('td');
 62	    hostCell.className = 'cred-host-cell';
 63	    hostCell.textContent = host;
 64	    tr.appendChild(hostCell);
 65	
 66	    // ---- Masked token cell (read-only) ----
 67	    const tokenCell = document.createElement('td');
 68	    tokenCell.className = 'cred-token-cell text-muted';
 69	    tokenCell.textContent = maskedToken;
 70	    tr.appendChild(tokenCell);
 71	
 72	    // ---- Actions cell ----
 73	    const actionsCell = document.createElement('td');
 74	    actionsCell.className = 'cred-actions-cell';
 75	
 76	    const deleteBtn = document.createElement('button');
 77	    deleteBtn.type = 'button';
 78	    deleteBtn.className = 'btn btn-danger btn-sm';
 79	    deleteBtn.textContent = 'Delete';
 80	
 81	    actionsCell.appendChild(deleteBtn);
 82	    tr.appendChild(actionsCell);
 83	
 84	    // ---- Behaviour ----
 85	
 86	    deleteBtn.addEventListener('click', async () => {
 87	        try {
 88	            await showConfirm(
 89	                'Delete Credential',
 90	                `Remove the credential for "${host}"? This action cannot be undone.`,
 91	            );
 92	        } catch {
 93	            // User cancelled — do nothing.
 94	            return;
 95	        }
 96	
 97	        deleteBtn.disabled = true;
 98	        deleteBtn.textContent = 'Deleting…';
 99	
100	        try {
101	            await api.config.credentials.delete(host);
102	            showToast(`Credential for "${host}" deleted.`, 'success');
103	            onDeleted();
104	        } catch (err) {
105	            showToast(err.message || 'Failed to delete credential.', 'error');
106	            deleteBtn.disabled = false;
107	            deleteBtn.textContent = 'Delete';
108	        }
109	    });
110	
111	    return tr;
112	}
113	
114	// ---------------------------------------------------------------------------
115	// Credentials table rendering
116	// ---------------------------------------------------------------------------
117	
118	/**
119	 * Render a loading indicator into `tableContainer`.
120	 *
121	 * @param {HTMLElement} tableContainer
122	 */
123	function showLoading(tableContainer) {
124	    tableContainer.innerHTML = `
125	        <div class="loading-indicator" aria-live="polite" aria-label="Loading credentials…">
126	            <span class="spinner" aria-hidden="true"></span>
127	            <span>Loading credentials…</span>
128	        </div>
129	    `;
130	}
131	
132	/**
133	 * Fetch all credentials and render them into `tableContainer`.
134	 *
135	 * @param {HTMLElement} tableContainer
136	 */
137	async function renderCredentialsTable(tableContainer) {
138	    showLoading(tableContainer);
139	
140	    let credentials;
141	    try {
142	        credentials = await api.config.credentials.list();
143	    } catch (err) {
144	        clearElement(tableContainer);
145	        const errorP = document.createElement('p');
146	        errorP.className = 'error-message';
147	        errorP.setAttribute('role', 'alert');
148	        errorP.textContent = `Failed to load credentials: ${err.message || 'Unknown error'}`;
149	        tableContainer.appendChild(errorP);
150	        return;
151	    }
152	
153	    const entries = Object.entries(credentials || {});
154	
155	    if (entries.length === 0) {
156	        tableContainer.innerHTML = `
157	            <p class="empty-state">No credentials configured. Use the form below to add one.</p>
158	        `;
159	        return;
160	    }
161	
162	    const table = document.createElement('table');
163	    table.className = 'credentials-table';
164	    table.setAttribute('role', 'table');
165	    table.setAttribute('aria-label', 'Git credentials');
166	
167	    table.appendChild(buildTableHead());
168	
169	    const tbody = document.createElement('tbody');
170	
171	    for (const [host, maskedToken] of entries) {
172	        tbody.appendChild(buildCredentialRow(host, maskedToken, () => {
173	            renderCredentialsTable(tableContainer);
174	        }));
175	    }
176	
177	    table.appendChild(tbody);
178	    clearElement(tableContainer);
179	    tableContainer.appendChild(table);
180	}
181	
182	// ---------------------------------------------------------------------------
183	// Add / Update credential form
184	// ---------------------------------------------------------------------------
185	
186	/**
187	 * Build the "Add / Update Credential" section with a toggle button and inline form.
188	 *
189	 * @param {HTMLElement} tableContainer - Used to trigger a refresh after a successful save.
190	 * @returns {HTMLElement} The wrapper element containing the toggle button and form.
191	 */
192	function buildAddCredentialForm(tableContainer) {
193	    const section = document.createElement('div');
194	    section.className = 'add-credential-section';
195	
196	    const toggleBtn = document.createElement('button');
197	    toggleBtn.type = 'button';
198	    toggleBtn.className = 'btn btn-primary';
199	    toggleBtn.textContent = 'Add / Update Credential';

201	    const formWrapper = document.createElement('div');
202	    formWrapper.className = 'form-wrapper';
203	    formWrapper.hidden = true;
204	
205	    const form = document.createElement('form');
206	    form.noValidate = true;
207	
208	    form.appendChild(createFormField('Host', 'text', 'host', {
209	        placeholder: 'e.g. github.com',
210	        required: true,
211	    }));
212	
213	    form.appendChild(createFormField('Token', 'password', 'token', {
214	        placeholder: 'Personal access token',
215	        required: true,
216	    }));
217	
218	    const actions = document.createElement('div');
219	    actions.className = 'form-actions';
220	
221	    const submitBtn = document.createElement('button');
222	    submitBtn.type = 'submit';
223	    submitBtn.className = 'btn btn-primary';
224	    submitBtn.textContent = 'Save';
225	
226	    const cancelBtn = document.createElement('button');
227	    cancelBtn.type = 'button';
228	    cancelBtn.className = 'btn btn-secondary';
229	    cancelBtn.textContent = 'Cancel';
230	
231	    actions.appendChild(submitBtn);
232	    actions.appendChild(cancelBtn);
233	    form.appendChild(actions);
234	    formWrapper.appendChild(form);
235	
236	    section.appendChild(toggleBtn);
237	    section.appendChild(formWrapper);
238	
239	    // ---- Behaviour ----
240	
241	    toggleBtn.addEventListener('click', () => {
242	        formWrapper.hidden = !formWrapper.hidden;
243	        if (!formWrapper.hidden) {
244	            const hostInput = form.querySelector('[name="host"]');
245	            if (hostInput) hostInput.focus();
246	        }
247	    });
248	
249	    cancelBtn.addEventListener('click', () => {
250	        form.reset();
251	        formWrapper.hidden = true;
252	    });
253	
254	    form.addEventListener('submit', async (e) => {
255	        e.preventDefault();
256	
257	        if (!validateRequired(form, ['host', 'token'])) return;
258	
259	        const host  = form.querySelector('[name="host"]').value.trim();
260	        const token = form.querySelector('[name="token"]').value.trim();
261	
262	        submitBtn.disabled = true;
263	        submitBtn.textContent = 'Saving…';
264	
265	        try {
266	            await api.config.credentials.set({ host, token });
267	            showToast(`Credential for "${host}" saved.`, 'success');
268	            form.reset();
269	            formWrapper.hidden = true;
270	            renderCredentialsTable(tableContainer);
271	        } catch (err) {
272	            showToast(err.message || 'Failed to save credential.', 'error');
273	        } finally {
274	            submitBtn.disabled = false;
275	            submitBtn.textContent = 'Save';
276	        }
277	    });
278	
279	    return section;
280	}
