286	/**
287	 * Build the "Repositories Refresh Delay" section.
288	 *
289	 * Fetches the current server-side `gitPollingIntervalSeconds` value on mount,
290	 * populates a number input, and exposes a `save()` function for the shared
291	 * settings footer button.
292	 *
293	 * @returns {{ element: HTMLElement, save: () => Promise<boolean> }}
294	 */
295	function buildRefreshDelaySection() {
296	    const section = document.createElement('section');
297	    section.className = 'settings-section refresh-delay-section';
298	
299	    const heading = document.createElement('h2');
300	    heading.textContent = 'Repositories Refresh Delay';
301	    section.appendChild(heading);
302	
303	    const description = document.createElement('p');
304	    description.textContent =
305	        'How often (in seconds) the server polls remote repositories for new commits. ' +
306	        'Changes take effect immediately — the current polling cycle is restarted with the new interval. ' +
307	        'Minimum value is 10 seconds.';
308	    section.appendChild(description);
309	
310	    // ---- Input row ----
311	    const inputRow = document.createElement('div');
312	    inputRow.className = 'refresh-delay-input-row';
313	
314	    const label = document.createElement('label');
315	    label.htmlFor = 'refresh-delay-input';
316	    label.textContent = 'Interval';
317	    label.className = 'refresh-delay-label';
318	
319	    const input = document.createElement('input');
320	    input.type = 'number';
321	    input.id = 'refresh-delay-input';
322	    input.name = 'refreshDelay';
323	    input.className = 'form-input refresh-delay-input';
324	    input.min = '10';
325	    // Maximum matches server-side MAX_POLLING_INTERVAL_SECONDS in src/config/config.constants.ts
326	    input.max = '86400';
327	    input.step = '1';
328	    input.placeholder = '30';
329	    input.setAttribute('aria-label', 'Polling interval in seconds');
330	
331	    const unitLabel = document.createElement('span');
332	    unitLabel.className = 'refresh-delay-unit';
333	    unitLabel.textContent = 'seconds';
334	
335	    inputRow.appendChild(label);
336	    inputRow.appendChild(input);
337	    inputRow.appendChild(unitLabel);
338	    section.appendChild(inputRow);
339	
340	    // ---- Inline error message ----
341	    const errorMsg = document.createElement('p');
342	    errorMsg.className = 'error-message';
343	    errorMsg.setAttribute('role', 'alert');
344	    errorMsg.hidden = true;
345	    section.appendChild(errorMsg);
346	
347	    // ---- Populate current value on mount ----
348	    (async () => {
349	        try {
350	            const cfg = await api.config.polling.get();
351	            if (cfg && typeof cfg.gitPollingIntervalSeconds === 'number') {
352	                input.value = String(cfg.gitPollingIntervalSeconds);
353	            }
354	        } catch {
355	            // Non-fatal — leave the placeholder in place.
356	        }
357	    })();
358	
359	    // ---- Save function (called by the shared footer button) ----
360	    async function save() {
361	        const raw   = input.value.trim();
362	        const value = Number(raw);
363	
364	        if (!raw || !Number.isFinite(value) || !Number.isInteger(value) || value < 10) {
365	            errorMsg.textContent = 'Please enter a whole number of 10 or more.';
366	            errorMsg.hidden = false;
367	            input.focus();
368	            return false;
369	        }
370	
371	        if (value > 86400) {
372	            errorMsg.textContent = 'Please enter a value of 86400 or less (24 hours maximum).';
373	            errorMsg.hidden = false;
374	            input.focus();
375	            return false;
376	        }
377	
378	        errorMsg.hidden = true;
379	
380	        try {
381	            await api.config.polling.set(value);
382	            return true;
383	        } catch (err) {
384	            showToast(err.message || 'Failed to save refresh delay.', 'error');
385	            return false;
386	        }
387	    }
388	
389	    return { element: section, save };
390	}
