392	// ---------------------------------------------------------------------------
393	// Webserver URL section
394	// ---------------------------------------------------------------------------
395	
396	/**
397	 * Build the "Webserver URL" section.
398	 *
399	 * Fetches the current server-side `webserverUrl` value on mount, populates a
400	 * text input, and exposes a `save()` function for the shared settings footer
401	 * button.
402	 *
403	 * @returns {{ element: HTMLElement, save: () => Promise<boolean> }}
404	 */
405	function buildWebserverUrlSection() {
406	    const section = document.createElement('section');
407	    section.className = 'settings-section webserver-url-section';
408	
409	    const heading = document.createElement('h2');
410	    heading.textContent = 'Webserver URL';
411	    section.appendChild(heading);
412	
413	    const description = document.createElement('p');
414	    description.textContent =
415	        'Base URL of the local webserver serving your workspace repositories. ' +
416	        'When set, a "Browse" button appears in the workspace-detail view for each ' +
417	        'repository. The URL should point to the root of your projects folder ' +
418	        '(e.g. http://localhost:8080). Leave empty to hide the Browse button.';
419	    section.appendChild(description);
420	
421	    // ---- Input row ----
422	    const inputRow = document.createElement('div');
423	    inputRow.className = 'webserver-url-input-row';
424	
425	    const label = document.createElement('label');
426	    label.htmlFor = 'webserver-url-input';
427	    label.textContent = 'URL';
428	    label.className = 'webserver-url-label';
429	
430	    const input = document.createElement('input');
431	    input.type = 'url';
432	    input.id = 'webserver-url-input';
433	    input.name = 'webserverUrl';
434	    input.className = 'form-input webserver-url-input';
435	    input.placeholder = 'http://localhost:8080';
436	    input.setAttribute('aria-label', 'Webserver base URL');
437	
438	    inputRow.appendChild(label);
439	    inputRow.appendChild(input);
440	    section.appendChild(inputRow);
441	
442	    // ---- Inline error message ----
443	    const errorMsg = document.createElement('p');
444	    errorMsg.className = 'error-message';
445	    errorMsg.setAttribute('role', 'alert');
446	    errorMsg.hidden = true;
447	    section.appendChild(errorMsg);
448	
449	    // ---- Populate current value on mount ----
450	    (async () => {
451	        try {
452	            const cfg = await api.config.webserverUrl.get();
453	            if (cfg && typeof cfg.webserverUrl === 'string') {
454	                input.value = cfg.webserverUrl;
455	            }
456	        } catch {
457	            // Non-fatal — leave the placeholder in place.
458	        }
459	    })();
460	
461	    // ---- Save function (called by the shared footer button) ----
462	    async function save() {
463	        errorMsg.hidden = true;
464	
465	        try {
466	            await api.config.webserverUrl.set(input.value.trim());
467	            return true;
468	        } catch (err) {
469	            showToast(err.message || 'Failed to save webserver URL.', 'error');
470	            return false;
471	        }
472	    }
473	
474	    return { element: section, save };
475	}
