481	/**
482	 * Render the Settings view into `container`.
483	 *
484	 * No cleanup function is returned because this view has no side-effects:
485	 * it does not start polling, install global event listeners, or hold any
486	 * external resources. The router does not need to call a teardown. This
487	 * is consistent with the `repositories` view, which follows the same pattern.
488	 *
489	 * @param {HTMLElement} container - The `#app` root element supplied by the router.
490	 * @param {Object}      _params   - Route params (none for this route).
491	 * @returns {void}
492	 */
493	export function renderSettings(container, _params) {
494	    document.title = 'Settings - ' + APP_NAME_SHORT;
495	    clearElement(container);
496	
497	    // Page heading
498	    const heading = document.createElement('h1');
499	    heading.textContent = 'Settings';
500	    container.appendChild(heading);

501	
502	    // Credentials section
503	    const credSection = document.createElement('section');
504	    credSection.className = 'settings-section';
505	
506	    const credHeading = document.createElement('h2');
507	    credHeading.textContent = 'Git Credentials';
508	    credSection.appendChild(credHeading);
509	
510	    const credDescription = document.createElement('p');
511	    credDescription.textContent =
512	        'Manage per-host personal access tokens used for authenticating with private repositories. Tokens are stored masked — only the last 4 characters are visible.';
513	    credSection.appendChild(credDescription);
514	
515	    const tableContainer = document.createElement('div');
516	    tableContainer.className = 'credentials-table-container';
517	    credSection.appendChild(tableContainer);
518	
519	    credSection.appendChild(buildAddCredentialForm(tableContainer));
520	    container.appendChild(credSection);
521	
522	    // Initial data load
523	    renderCredentialsTable(tableContainer);
524	
525	    // ---- Remaining sections ----
526	    const refreshDelay = buildRefreshDelaySection();
527	    container.appendChild(refreshDelay.element);
528	
529	    const webserverUrl = buildWebserverUrlSection();
530	    container.appendChild(webserverUrl.element);
531	
532	    // ---- Form footer ----
533	    const footer = document.createElement('footer');
534	    footer.className = 'settings-footer';
535	
536	    const saveBtn = document.createElement('button');
537	    saveBtn.type = 'button';
538	    saveBtn.className = 'btn btn-primary';
539	    saveBtn.textContent = 'Save Settings';
540	    footer.appendChild(saveBtn);
541	    container.appendChild(footer);
542	
543	    saveBtn.addEventListener('click', async () => {
544	        saveBtn.disabled = true;
545	        saveBtn.textContent = 'Saving…';
546	
547	        try {
548	            const results = await Promise.all([
549	                refreshDelay.save(),
550	                webserverUrl.save(),
551	            ]);
552	
553	            if (results.every(Boolean)) {
554	                showToast('Settings saved.', 'success');
555	            }
556	        } finally {
557	            saveBtn.disabled = false;
558	            saveBtn.textContent = 'Save Settings';
559	        }
560	    });
561	}

